update fragen set frage = $q$Schreibe eine Abfrage, die ALLE Kunden mit ihren Bestellungen anzeigt, auch Kunden ohne Bestellungen. Tabellen: "kunden" (id, name) und "bestellungen" (id, kunde_id, datum). Zeige kunden.name und bestellungen.datum.$q$, erklaerung = $q$SELECT kunden.name, bestellungen.datum FROM kunden LEFT JOIN bestellungen ON kunden.id = bestellungen.kunde_id. LEFT JOIN nimmt ALLE Kunden mit. Bei fehlenden Bestellungen erscheint NULL beim Datum.$q$ where id = 210722;
update fragen set erklaerung = $q$WHERE filtert einzelne Zeilen VOR dem GROUP BY. HAVING filtert Gruppen NACH dem GROUP BY und kann mit Aggregat-Funktionen wie COUNT(*) oder AVG() arbeiten, was WHERE nicht kann.$q$ where id = 210725;
update fragen set erklaerung = $q$AVG() ignoriert NULL-Werte automatisch. Sie werden nicht mitgezählt. So wird der Durchschnitt nicht durch fehlende Werte verfälscht.$q$ where id = 210726;
update fragen set erklaerung = $q$GROUP BY gruppiert die Zeilen nach dem angegebenen Wert. Die Aggregat-Funktion (COUNT) wird dann pro Gruppe ausgeführt.$q$ where id = 210727;
update fragen set erklaerung = $q$DEFAULT setzt einen Standardwert. Wenn beim INSERT kein Wert angegeben wird, nutzt die DB diesen Standard, z.B. DEFAULT 0, DEFAULT NOW() oder DEFAULT 'aktiv'.$q$ where id = 210733;
update fragen set erklaerung = $q$CREATE TABLE legt eine neue Tabelle an. Die Spalten werden in Klammern definiert (pro Spalte: Name, Typ und optionale Constraints).$q$ where id = 210734;
update fragen set erklaerung = $q$1NF: Alle Werte müssen atomar (unteilbar) sein. Eine Spalte „telefon“ mit dem Wert „0171/123, 0151/456“ verletzt 1NF. Besser sind entweder zwei Spalten (telefon1, telefon2) oder eine eigene Tabelle telefonnummern.$q$ where id = 210736;
update fragen set erklaerung = $q$n:m-Beziehungen lassen sich nicht direkt abbilden. Man braucht eine Verbindungstabelle (auch: Zuordnungstabelle, Junction Table). Beispiel: schueler ↔ kurse → Tabelle schueler_kurse mit den Spalten schueler_id und kurs_id.$q$ where id = 210738;
update fragen set erklaerung = $q$Normalisierung reduziert Redundanz (mehrfach gespeicherte gleiche Daten) und vermeidet Anomalien beim Einfügen, Ändern und Löschen. Daten sind konsistent, weil sie nur an einer Stelle stehen. Performance ist NICHT der Hauptvorteil. Bei sehr vielen JOINs kann Normalisierung Abfragen sogar verlangsamen.$q$ where id = 210739;
update fragen set erklaerung = $q$Eine Subquery ist eine Abfrage innerhalb einer anderen. Sie steht in Klammern und wird zuerst ausgeführt. Ihr Ergebnis nutzt die äußere Abfrage dann z.B. für einen Vergleich oder Filter.$q$ where id = 210744;
update fragen set erklaerung = $q$DISTINCT entfernt Duplikate aus dem Ergebnis. Nur einzigartige Werte werden zurückgegeben. Beispiel: SELECT DISTINCT stadt FROM kunden gibt jede Stadt nur einmal zurück, auch wenn dort mehrere Kunden wohnen.$q$ where id = 210745;
update fragen set erklaerung = $q$LAN steht für Local Area Network, ein lokales, räumlich begrenztes Netzwerk, z.B. ein Heimnetz oder ein Firmenbüro.$q$ where id = 210750;
update fragen set erklaerung = $q$Ein Switch sendet Pakete gezielt an den richtigen Empfänger (lernt MAC-Adressen). Ein Hub sendet jedes Paket an ALLE Geräte, daher veraltet und unsicher.$q$ where id = 210753;
update fragen set erklaerung = $q$Wahr. Das Internet ist das größte Wide Area Network der Welt. Es verbindet Milliarden von Geräten weltweit über viele kleine LANs miteinander.$q$ where id = 210754;
update fragen set erklaerung = $q$1en markieren den Netz-Anteil, 0en markieren den Host-Anteil. Eine Maske ist immer eine Folge aus 1en, gefolgt von 0en, niemals gemischt.$q$ where id = 210763;
update fragen set erklaerung = $q$Die CIDR-Notation /24 entspricht 255.255.255.0, denn die ersten 24 Bits (= 3 Oktette) sind auf 1 gesetzt.$q$ where id = 210765;
update fragen set erklaerung = $q$Falsch. Die CIDR-Zahl kann jeden Wert von /0 bis /32 annehmen, z.B. auch /26 oder /30. Dass sie auf Oktett-Grenzen liegt (/8, /16, /24) ist nur bei einfachen Netzen üblich. Bei kleineren Subnetzen sind andere Werte normal.$q$ where id = 210766;
update fragen set erklaerung = $q$Wahr. Private IPs sind nur im eigenen LAN gültig. Sie können sich in unzähligen Heimnetzen weltweit wiederholen, ohne dass es Konflikte gibt. Erst wenn der Datenverkehr ins Internet geht, übersetzt NAT die private in eine öffentliche IP.$q$ where id = 210771;
update fragen set erklaerung = $q$MAC-Adressen werden in Hexadezimal-Notation geschrieben, als 6 Paare aus jeweils 2 Hex-Zeichen, getrennt durch Doppelpunkte (oder seltener durch Bindestriche). Beispiel: AA:BB:CC:11:22:33.$q$ where id = 210776;
update fragen set erklaerung = $q$/27 → Block-Größe 32. 45÷32 = 1 (abgerundet). 1×32 = 32. Netzadresse: 10.0.0.32. Die IP liegt im Bereich 10.0.0.32 bis 10.0.0.63.$q$ where id = 210797;
update fragen set erklaerung = $q$0.0.0.0/0 ist die Default-Route. Sie matcht alle IP-Adressen, die nicht von einer spezifischeren Route abgedeckt sind. Ein Paket geht über die Default-Route, wenn keine andere passt.$q$ where id = 210804;
update fragen set erklaerung = $q$Wahr. Im selben LAN braucht ein Gerät kein Gateway. Es spricht direkt mit anderen Geräten über deren MAC-Adresse (via ARP). Das Gateway wird nur benötigt, wenn das Ziel AUSSERHALB des eigenen Netzes liegt (z.B. Internet).$q$ where id = 210806;
update fragen set erklaerung = $q$IPv6-Adressen sind 128 Bit lang, genau das Vierfache von IPv4 (32 Bit). Das ergibt 2^128 mögliche Adressen.$q$ where id = 210808;
update fragen set erklaerung = $q$Wahr. Da jedes Gerät bei IPv6 seine eigene öffentliche Adresse haben kann (es gibt genug davon), entfällt die Notwendigkeit für NAT. Die Architektur wird einfacher und Ende-zu-Ende-Verbindungen sind direkt möglich.$q$ where id = 210812;
update fragen set erklaerung = $q$/27 → Block-Größe 32. Subnetz: 172.16.10.0 bis 172.16.10.31. Erste Host-IP: .1, letzte Host-IP: .30, Broadcast: .31. Damit ist 172.16.10.31 der Broadcast und somit die richtige Antwort.$q$ where id = 210817;
update fragen set erklaerung = $q$Die Vertraulichkeit (Confidentiality) wird verletzt. Eine unbefugte Person greift auf Informationen zu, die nur für Befugte bestimmt sind.$q$ where id = 210822;
update fragen set erklaerung = $q$Die Integrität wird verletzt. Daten werden unbemerkt manipuliert. Schutz dagegen sind z.B. digitale Signaturen oder Hashwerte.$q$ where id = 210823;
update fragen set erklaerung = $q$Die Verfügbarkeit wird verletzt. Legitime Nutzer können nicht mehr auf den Dienst zugreifen, weil das System überlastet ist.$q$ where id = 210824;
update fragen set frage = $q$Wahr oder falsch: Die drei Schutzziele der CIA-Triade lassen sich immer gleichzeitig MAXIMAL erreichen und stehen nie im Konflikt.$q$ where id = 210825;
update fragen set erklaerung = $q$Ein Virus benötigt eine Wirts-Datei (z.B. ein Programm) und verbreitet sich, wenn diese ausgeführt wird. Ein Wurm verbreitet sich SELBSTÄNDIG über Netzwerke. Er braucht keine Wirts-Datei und keine Nutzeraktion.$q$ where id = 210828;
update fragen set erklaerung = $q$Phishing ist der Versuch, über gefälschte E-Mails oder Webseiten an sensible Daten zu kommen, z.B. Login-Daten oder Kreditkarteninformationen. Der Name kommt von „fishing", also Daten „angeln".$q$ where id = 210829;
update fragen set erklaerung = $q$Social Engineering nutzt psychologische Manipulation. Anstatt technische Sicherheitslücken auszunutzen, wird der Mensch ausgetrickst. Beispiele: gefälschte IT-Support-Anrufe, Vortäuschung von Autorität, Ausnutzung von Hilfsbereitschaft.$q$ where id = 210831;
update fragen set erklaerung = $q$Wahr. Der Name kommt vom „trojanischen Pferd": Die Schadsoftware versteckt sich in einer harmlos wirkenden Anwendung (z.B. einem Spiel oder Tool) und wird vom Nutzer freiwillig ausgeführt.$q$ where id = 210832;
update fragen set erklaerung = $q$Ein Fingerabdruck gehört zur Biometrie, also etwas, das du BIST. Die drei Faktoren sind Wissen (Passwort), Besitz (Token) und Biometrie.$q$ where id = 210835;
update fragen set erklaerung = $q$Wenn die Datenbank kompromittiert wird (durch Hack, Insider, Backup-Diebstahl), wären alle Passwörter sofort lesbar. Und da viele Nutzer Passwörter wiederverwenden, hätte der Angreifer Zugriff auf weitere Dienste. Mit Hashing sind die Passwörter selbst dann geschützt.$q$ where id = 210836;
update fragen set erklaerung = $q$Ein Salt ist eine zufällige Zeichenkette, die VOR dem Hashen ans Passwort gehängt wird. Dadurch produzieren gleiche Passwörter unterschiedliche Hashes, was Rainbow-Table-Angriffe nutzlos macht.$q$ where id = 210837;
update fragen set erklaerung = $q$MD5 ist seit Jahren als unsicher eingestuft. Er ist zu schnell (was Brute-Force erleichtert) und hat bekannte Kollisions-Schwachstellen. Moderne Empfehlungen: bcrypt, scrypt oder Argon2.$q$ where id = 210838;
update fragen set erklaerung = $q$Das Schlüsselaustausch-Problem: Beide Parteien brauchen denselben geheimen Schlüssel. Aber wie tauschen sie ihn sicher aus, ohne dass ein Lauscher ihn abfängt? Asymmetrische Verfahren lösen das.$q$ where id = 210842;
update fragen set erklaerung = $q$Wahr. HTTPS ist ein hybrides Verfahren: Asymmetrisch wird benutzt, um initial einen sicheren Session-Key auszutauschen. Danach läuft die eigentliche Kommunikation symmetrisch. Das ist viel schneller für große Datenmengen.$q$ where id = 210844;
update fragen set erklaerung = $q$AES gibt es in drei Varianten: AES-128 (128 Bit), AES-192 und AES-256. Das Minimum ist AES-128, das heute noch als sicher gilt.$q$ where id = 210846;
update fragen set erklaerung = $q$DES nutzt nur 56 Bit Schlüssellänge. Mit moderner Hardware kann ein DES-Schlüssel innerhalb weniger Stunden per Brute-Force geknackt werden. Daher wird DES nicht mehr empfohlen.$q$ where id = 210847;
update fragen set erklaerung = $q$3DES wendet den DES-Algorithmus dreimal mit unterschiedlichen Schlüsseln an. Das vergrößert effektiv die Schlüssellänge und macht den Algorithmus deutlich sicherer als DES, dient aber heute nur als Übergangslösung.$q$ where id = 210848;
update fragen set erklaerung = $q$Sichere Hashes sind Einweg, deterministisch, kollisionsfrei und haben den Avalanche-Effekt. „Reversibel" ist GENAU DAS GEGENTEIL: Ein guter Hash darf nicht zurückrechenbar sein.$q$ where id = 210859;
update fragen set erklaerung = $q$SHA-1 gilt seit 2017 als gebrochen. Forscher haben praktische Kollisionen erzeugt (Google SHAttered). Für Signaturen und Zertifikate sollte mindestens SHA-256 genutzt werden.$q$ where id = 210860;
update fragen set erklaerung = $q$Asymmetrische Verschlüsselung ist langsam und für große Datenmengen ungeeignet. Daher wird nur der kurze Hash mit dem Private Key verschlüsselt. Das Ergebnis ist gleichwertig sicher und um Größenordnungen schneller.$q$ where id = 210862;
update fragen set erklaerung = $q$Eine Signatur garantiert Echtheit (vom Sender) und Integrität (unverändert). Sie garantiert NICHT Vertraulichkeit: Wer das Dokument abfängt, kann es lesen, da nur die Signatur mit dem Private Key verschlüsselt wurde, nicht das Dokument selbst. Für Vertraulichkeit braucht man zusätzliche Verschlüsselung.$q$ where id = 210863;
update fragen set erklaerung = $q$Eine DMZ (Demilitarized Zone) ist ein Pufferbereich zwischen Internet und internem Netzwerk. Dort stehen öffentlich erreichbare Server (Webserver, Mailserver). Wenn die kompromittiert werden, hat der Angreifer noch nicht Zugriff aufs interne Netz.$q$ where id = 210866;
update fragen set erklaerung = $q$Ein VPN baut einen verschlüsselten Tunnel durch ein unsicheres Netzwerk (z.B. das Internet) auf. So kann man sicher auf entfernte Netze zugreifen, z.B. aus dem Home-Office aufs Firmennetz.$q$ where id = 210867;
update fragen set erklaerung = $q$OWASP = Open Web Application Security Project. Eine internationale Community, die Sicherheits-Standards für Webanwendungen entwickelt, bekannt vor allem durch die OWASP Top 10.$q$ where id = 210872;
update fragen set erklaerung = $q$Prepared Statements (parameterisierte Queries) trennen SQL-Code von Daten. Der Nutzer-Input wird IMMER als Wert behandelt, nie als Code. Input-Filterung allein ist fehleranfällig. Prepared Statements sind der Goldstandard.$q$ where id = 210873;
update fragen set erklaerung = $q$Output-Escaping wandelt Sonderzeichen wie <, >, " in HTML-Entities um (&lt;, &gt;, &quot;). Damit kann der Browser den Inhalt nicht als Code interpretieren, nur noch als Text anzeigen.$q$ where id = 210875;
update fragen set erklaerung = $q$Zero Trust geht davon aus, dass NIEMAND von Haus aus vertrauenswürdig ist, auch nicht im internen Netz. Bei jedem Zugriff wird neu authentifiziert und geprüft. Motto: „Never trust, always verify".$q$ where id = 210880;
update fragen set erklaerung = $q$Das ist „Baiting", eine Form von Social Engineering. Der Angreifer platziert einen verseuchten USB-Stick und setzt auf die Neugier des Opfers. Sobald der Stick eingesteckt wird, kann Schadsoftware automatisch ausgeführt werden.$q$ where id = 210885;
update fragen set erklaerung = $q$Mitarbeiter-Schulung (Awareness) ist der wichtigste Schutz vor Phishing. Über 80% aller Cyber-Angriffe beginnen mit Social Engineering oder Phishing. Keine technische Maßnahme schützt zuverlässig, wenn der Mensch klickt. MFA hilft zwar, aber Schulung ist die Wurzel.$q$ where id = 210886;
update fragen set erklaerung = $q$Eine digitale Signatur garantiert primär Integrität (Daten unverändert) und Authentizität (vom angegebenen Absender). Sie verschlüsselt aber NICHT den Inhalt. Dafür braucht man zusätzliche Verschlüsselung (Confidentiality).$q$ where id = 210887;
update fragen set erklaerung = $q$Offline- bzw. Immutable-Backups sind der zuverlässigste Schutz. Selbst wenn Ransomware das System verschlüsselt, sind Offline-Backups davon nicht betroffen. Antivirus + Firewall reduzieren das Risiko, aber kein technischer Schutz ist 100%, daher sind Backups die letzte Verteidigung.$q$ where id = 210888;
update fragen set erklaerung = $q$Mitarbeiter-Schulungen sind eine ORGANISATORISCHE Maßnahme. Sie ändern Verhalten, nicht Technik. Firewall, Verschlüsselung und MFA sind technische Maßnahmen. In der IHK-Prüfung ist die Unterscheidung wichtig. Gute Antworten kombinieren beides.$q$ where id = 210889;
update fragen set erklaerung = $q$Es handelt sich um einen DDoS-Angriff (Distributed Denial of Service). Dabei kommen aus vielen Quellen massiv Anfragen, um den Server zu überlasten. Betroffen ist die Verfügbarkeit (Availability) der CIA-Triade.$q$ where id = 210890;
update fragen set frage = $q$Wahr oder falsch: Ein Bit kann genau zwei Zustände haben (0 oder 1).$q$ where id = 210896;
update fragen set erklaerung = $q$Das MSB (Most Significant Bit, ganz links) ist das Vorzeichenbit: 0 = positive Zahl, 1 = negative Zahl. Bei unsigned Zahlen hat es diese Bedeutung NICHT. Dort zählt es als normaler Stellenwert.$q$ where id = 210924;
update fragen set erklaerung = $q$248 = 1111 1000 (= 128+64+32+16+8). Das sind 5 Einsen. Diese Subnetzmaske entspricht /29, typisch für kleine Punkt-zu-Punkt-Netze.$q$ where id = 210932;
update fragen set frage = $q$Welcher Binärwert entspricht in der MAC-Adresse 00:1B:44:11:3A:B7 dem 5. Byte (3A)?$q$ where id = 210934;
update fragen set erklaerung = $q$OSI steht für „Open Systems Interconnection", übersetzt etwa „Verbindung offener Systeme". Das Modell wurde von der ISO entwickelt, um Hersteller-übergreifende Kommunikation zu ermöglichen.$q$ where id = 210938;
update fragen set erklaerung = $q$Das OSI-Modell besteht aus genau 7 Schichten, von Schicht 1 (Bitübertragung) bis Schicht 7 (Anwendung).$q$ where id = 210939;
update fragen set erklaerung = $q$Ein Hub arbeitet ausschließlich auf Schicht 1. Er verteilt eingehende Signale unverändert an alle Ports und kennt keine MAC-Adressen. Switch und Bridge sind Schicht-2-Geräte, ein Router arbeitet auf Schicht 3.$q$ where id = 210948;
update fragen set erklaerung = $q$Schicht 3 sorgt für die logische Adressierung (IP-Adressen) und das Routing, also die Wegewahl der Datenpakete durch verschiedene Netzwerke. Sie kümmert sich darum, wie Pakete vom Sender zum Empfänger gelangen, auch über Netzgrenzen hinweg.$q$ where id = 210950;
update fragen set erklaerung = $q$Bei Video- oder Sprach-Anrufen (VoIP, Streaming) ist Geschwindigkeit wichtiger als Vollständigkeit. Wenn ein Frame verloren geht, würde TCP es erneut anfordern. Bei einem Live-Anruf wäre das aber zu spät und würde Verzögerungen verursachen. UDP überspringt verlorene Pakete einfach.$q$ where id = 210954;
update fragen set erklaerung = $q$Wahr. Das TCP/IP-Modell wurde zusammen mit konkreten Protokollen (TCP, IP, UDP, HTTP usw.) entwickelt und ist heute Grundlage des Internets. Das OSI-Modell ist dagegen ein reines Referenzmodell. Eigene OSI-Protokolle haben sich nie durchgesetzt.$q$ where id = 210972;
update fragen set erklaerung = $q$DNS (Domain Name System) löst Domainnamen in IP-Adressen auf und gehört zu den Anwendungsprotokollen, also Schicht 7. Wichtig: DNS NUTZT zwar UDP/TCP (Schicht 4) für die Übertragung, ist aber selbst ein Schicht-7-Protokoll.$q$ where id = 210975;
update fragen set erklaerung = $q$ICMP (Internet Control Message Protocol) gehört zu Schicht 3 (Vermittlung). Es wird für Diagnose und Fehlermeldungen genutzt (typische Anwendung: ping und traceroute). ICMP nutzt direkt IP, nicht TCP oder UDP.$q$ where id = 210977;
update fragen set erklaerung = $q$IP = Schicht 3 (Vermittlung), TCP = Schicht 4 (Transport), HTTP = Schicht 7 (Anwendung). Diese Reihenfolge folgt dem Datenfluss von unten nach oben: IP transportiert das Paket, TCP sorgt für Zuverlässigkeit, HTTP definiert die Anwendungslogik.$q$ where id = 210979;
update fragen set frage = $q$Welches Protokoll wird zur Auflösung einer IP-Adresse in eine MAC-Adresse verwendet, und auf welcher Schicht?$q$ where id = 210980;
update fragen set erklaerung = $q$Wenn das lokale Netz (Schicht 1+2) funktioniert, aber die Internetverbindung nicht, liegt das Problem typischerweise auf Schicht 3 (Vermittlung), z. B. Router-Ausfall oder fehlerhafte Routing-Tabelle. Auch DNS-Probleme (Schicht 7) sind denkbar, aber Schicht 3 ist der häufigste Fall.$q$ where id = 210983;
update fragen set erklaerung = $q$Ein Layer-3-Switch kombiniert die Funktionen eines normalen Switch (Schicht 2, MAC-basiertes Forwarding) mit Routing-Funktionen (Schicht 3, IP-basiert). Er arbeitet also auf den Schichten 1, 2 UND 3, nicht nur auf Schicht 3.$q$ where id = 210984;
update fragen set erklaerung = $q$Falsch. Beim Sender gehen die Daten von OBEN nach UNTEN: Anwendung (7) → Darstellung (6) → ... → Bitübertragung (1). Jede Schicht fügt einen Header hinzu (Encapsulation). Beim Empfänger ist es umgekehrt: von unten nach oben (Decapsulation).$q$ where id = 210985;
update fragen set erklaerung = $q$Wiederkehrende Tätigkeiten sind das Gegenteil eines Projekts. Das ist Routinearbeit. Projekte sind einmalig, zielorientiert, zeitlich befristet und komplex.$q$ where id = 210989;
update fragen set erklaerung = $q$Die Migration eines ERP-Systems ist einmalig, hat ein klares Ziel, ist zeitlich begrenzt und komplex. Alle Projekt-Merkmale sind erfüllt. Tagesgeschäft (Backups, Helpdesk-Tickets, Routine-Wartung) sind dagegen wiederkehrende Tätigkeiten.$q$ where id = 210991;
update fragen set erklaerung = $q$Das Pflichtenheft wird typischerweise am Ende der Initiierungsphase erstellt, als Antwort des Auftragnehmers auf das Lastenheft des Auftraggebers. Es beschreibt das WIE der Umsetzung.$q$ where id = 210996;
update fragen set erklaerung = $q$Ein Meilenstein ist ein wichtiges Ereignis ohne Dauer, typischerweise das Ende einer Phase oder ein Kontrollpunkt. In Gantt-Diagrammen wird er als Raute dargestellt. Beispiel: Projektauftrag erteilt, Pflichtenheft genehmigt.$q$ where id = 210998;
update fragen set erklaerung = $q$Der Projektleiter ist für die operative Durchführung verantwortlich. Er plant, steuert, koordiniert das Team und berichtet an den Auftraggeber. Der Auftraggeber definiert die Ziele und finanziert, setzt aber nicht selbst um.$q$ where id = 211001;
update fragen set erklaerung = $q$Ein Stakeholder ist jede Person oder Gruppe, die das Projekt beeinflussen kann oder davon betroffen ist, egal ob positiv oder negativ. Auch Projektgegner und Betroffene zählen dazu, nicht nur Befürworter.$q$ where id = 211002;
update fragen set erklaerung = $q$Falsch. In der typischen Matrix-Organisation hat der Projektleiter NUR fachliche Weisungsbefugnis. Die disziplinarische bleibt bei den ursprünglichen Vorgesetzten der Team-Mitglieder. Das macht das Projektmanagement oft anspruchsvoll.$q$ where id = 211005;
update fragen set erklaerung = $q$Das magische Dreieck besteht aus Zeit (Termine), Kosten (Budget) und Qualität (Leistung). Diese drei Faktoren stehen im Spannungsfeld zueinander: Du kannst nicht alle gleichzeitig optimieren.$q$ where id = 211007;
update fragen set erklaerung = $q$M steht für Messbar. Ziele sollten quantifizierbar sein, also mit konkreten Zahlen oder Kennzahlen versehen, z. B. Ladezeit auf 2 Sekunden reduzieren statt einfach schneller machen.$q$ where id = 211008;
update fragen set erklaerung = $q$Wenn die Zeit verkürzt wird, müssen entweder die Kosten steigen (mehr Personal, Überstunden) oder die Qualität sinken (weniger Features, Tests reduzieren). Beide Faktoren oder eine Kombination sind möglich. Alle drei können nicht gleichzeitig konstant bleiben.$q$ where id = 211010;
update fragen set erklaerung = $q$Klassische Gliederungen sind: objektorientiert (nach Komponenten), funktionsorientiert (nach Tätigkeiten) und phasenorientiert (nach Projektphasen). Eine kostenorientierte Gliederung gibt es im klassischen PSP nicht. Kosten ergeben sich aus den Arbeitspaketen.$q$ where id = 211014;
update fragen set erklaerung = $q$Der PSP zeigt nur die WAS-Frage (welche Aufgaben gibt es) und ihre hierarchische Struktur. Er enthält KEINE zeitliche Reihenfolge oder Termine. Dafür sind Gantt-Diagramme und Netzpläne zuständig. Aufwand, Verantwortliche und Kosten gehören aber zum AP.$q$ where id = 211015;
update fragen set erklaerung = $q$Ein Arbeitspaket hat einen Verantwortlichen, einen geschätzten Aufwand und ein klares Ergebnis. Eine eigene Projektorganisation gehört NICHT zum AP. Die existiert auf Projektebene, nicht je AP.$q$ where id = 211017;
update fragen set erklaerung = $q$Meilensteine werden als Raute (◇) dargestellt. Sie haben keine Dauer, sondern markieren nur einen Zeitpunkt (z. B. Projektabnahme, Phasenende). Ein Balken passt nicht, weil ein Meilenstein keine Dauer hat.$q$ where id = 211020;
update fragen set erklaerung = $q$Ende-Anfang (EA) ist die häufigste Beziehung. Vorgang B kann erst starten, wenn Vorgang A beendet ist. Beispiel: Erst Pflichtenheft schreiben, dann mit der Entwicklung starten.$q$ where id = 211021;
update fragen set erklaerung = $q$Ein Gantt-Diagramm zeigt Termine, Dauern und einfache Abhängigkeiten. Den kritischen Pfad und Pufferzeiten sieht man dort jedoch NICHT direkt. Dafür braucht man den Netzplan.$q$ where id = 211022;
update fragen set erklaerung = $q$Die Vorwärtsrechnung erfolgt von links nach rechts, vom Projektstart zum Projektende. Sie berechnet die frühesten Anfangs- und Endzeitpunkte (FAZ, FEZ).$q$ where id = 211026;
update fragen set erklaerung = $q$Bei mehreren Vorgängern wird IMMER das MAXIMUM der FEZ-Werte aller Vorgänger genommen. Logik: Der Vorgang kann erst starten, wenn ALLE Vorgänger fertig sind, also wenn der langsamste fertig ist.$q$ where id = 211028;
update fragen set erklaerung = $q$GP = SAZ - FAZ = 5 - 5 = 0. Der Vorgang hat keinen Spielraum. Er liegt auf dem kritischen Pfad. Jede Verzögerung von B würde das Projektende um die gleiche Zeit nach hinten schieben.$q$ where id = 211029;
update fragen set erklaerung = $q$Bei mehreren Nachfolgern wird IMMER das MINIMUM der SAZ-Werte genommen, also SEZ = 6. Logik: Der Vorgang muss spätestens enden, wenn der ZEITKRITISCHSTE Nachfolger startet, sonst gefährdet er den ganzen Plan.$q$ where id = 211030;
update fragen set erklaerung = $q$Alle Vorgänge auf dem kritischen Pfad haben einen Gesamtpuffer (GP) von 0. Das bedeutet: Sie haben keinen Spielraum. Jede Verzögerung verschiebt das Projektende.$q$ where id = 211033;
update fragen set erklaerung = $q$Vorwärtsrechnung: A endet bei 3, B endet bei 8, C endet bei 7, D startet bei MAX(8,7)=8 und endet bei 10. Pfad A→B→D = 3+5+2 = 10 Tage. Pfad A→C→D = 3+4+2 = 9 Tage. Der längere Pfad ist A→B→D mit 10 Tagen. Das ist der kritische Pfad und auch die Projektdauer.$q$ where id = 211034;
update fragen set erklaerung = $q$Wenn ein kritischer Vorgang sich verzögert, verschiebt sich das Projektende um genau die gleiche Zeit nach hinten, denn auf dem kritischen Pfad ist der Gesamtpuffer = 0. Das Projekt verzögert sich also um 3 Tage.$q$ where id = 211035;
update fragen set frage = $q$Vorgang X hat einen Gesamtpuffer von 2 Tagen. Wenn er sich um 5 Tage verzögert, wie wirkt sich das auf das Projekt aus?$q$ where id = 211036;
update fragen set erklaerung = $q$Nur die Verkürzung eines kritischen Vorgangs verkürzt die Projektdauer. Vorgänge mit Puffer haben Spielraum, der NICHT auf dem kritischen Pfad liegt. Sie zu beschleunigen bringt nichts für das Projektende. Goldene Regel: Beschleunigung lohnt sich nur auf dem kritischen Pfad.$q$ where id = 211037;
update fragen set erklaerung = $q$Risikowert = Eintrittswahrscheinlichkeit × Schadenshöhe (R = W × S). Der Wert ist ein Erwartungswert und hilft beim Vergleich verschiedener Risiken. Er zeigt, wo sich Investition in Vorbeugung lohnt.$q$ where id = 211039;
update fragen set erklaerung = $q$Die vier klassischen Strategien sind: Vermeiden, Vermindern, Übertragen, Akzeptieren. Ignorieren ist KEINE Strategie. Auch beim Akzeptieren wird das Risiko bewusst getragen, oft mit einer Rücklage.$q$ where id = 211040;
update fragen set erklaerung = $q$Das Lastenheft beschreibt das WAS, also die Anforderungen vom Auftraggeber an den Auftragnehmer. Das Pflichtenheft (vom Auftragnehmer erstellt) beschreibt dann das WIE der Umsetzung.$q$ where id = 211045;
update fragen set erklaerung = $q$Wenn Zeit reduziert werden soll und Qualität konstant bleibt, müssen die Kosten steigen, z. B. durch zusätzliches Personal oder Überstunden. Im magischen Dreieck kann man nicht alle drei Faktoren gleichzeitig optimieren.$q$ where id = 211046;
update fragen set erklaerung = $q$Auftraggeber (Geschäftsführer), Projektleiter (externer Berater) und Projektteam (IT-Team) sind die drei genannten Rollen. Der Lenkungsausschuss als eigene Rolle wurde nicht erwähnt. Er wäre sinnvoll, ist aber nicht zwingend in jedem Projekt vorhanden.$q$ where id = 211048;
update fragen set erklaerung = $q$Risikowert = 0,25 × 80.000 = 20.000 EUR (erwarteter Schaden pro Jahr). Die Versicherung kostet 5.000 EUR, also viel weniger als der Erwartungswert. Wirtschaftlich gesehen lohnt sich die Versicherung. Sie ist eine Risiko-Übertragung.$q$ where id = 211049;
update fragen set erklaerung = $q$Das Wiederherstellen von Daten aus einem Backup nennt man Recovery (deutsch: Wiederherstellung). Das ist der eigentliche Sinn eines Backups: im Notfall die Daten zurückzubekommen.$q$ where id = 211053;
update fragen set erklaerung = $q$Falsch. Daten an nur einem Ort sind NICHT sicher: Geht dieser Ort verloren (Defekt, Diebstahl, Malware), sind die Daten weg. Erst eine Kopie an einem getrennten Ort macht Daten wirklich sicher.$q$ where id = 211056;
update fragen set erklaerung = $q$Ein Vollbackup sichert immer ALLE Daten komplett, unabhängig davon, ob sich etwas geändert hat. Vorteil: einfache Wiederherstellung. Nachteil: viel Speicher und Zeit.$q$ where id = 211058;
update fragen set erklaerung = $q$Wahr. Da das differenzielle Backup immer alle Änderungen seit dem letzten Vollbackup sichert, sammelt es täglich mehr Daten an und wächst, bis ein neues Vollbackup den Bezugspunkt zurücksetzt.$q$ where id = 211063;
update fragen set erklaerung = $q$Die „1" steht für eine Kopie an einem anderen Ort (offsite), z.B. in der Cloud oder einem anderen Gebäude. Diese überlebt lokale Katastrophen wie Feuer, Wasser oder Diebstahl.$q$ where id = 211067;
update fragen set frage = $q$Ein Unternehmen hat 3 Backups, alle auf Festplatten im selben Serverraum. Welches Prinzip der 3-2-1-Regel wird hier VERLETZT?$q$, erklaerung = $q$Es fehlt die Offsite-Kopie (die „1"). Alle Backups stehen am selben Ort. Bei Feuer, Wasserschaden oder Diebstahl wäre alles gleichzeitig verloren. Außerdem ist nur ein Medientyp im Einsatz.$q$ where id = 211069;
update fragen set erklaerung = $q$GFS steht für Grandfather-Father-Son, ein Rotationsschema, das monatliche (Grandfather), wöchentliche (Father) und tägliche (Son) Backups kombiniert.$q$ where id = 211072;
update fragen set erklaerung = $q$Der „Son" (Sohn) sind die täglichen Backups, die jüngste und häufigste Generation. Sie werden am kürzesten aufgehoben und regelmäßig überschrieben.$q$ where id = 211073;
update fragen set erklaerung = $q$Der „Grandfather" (Großvater) sind die monatlichen Backups, die älteste Generation. Sie werden am längsten aufgehoben (oft 12 Monate oder mehr).$q$ where id = 211074;
update fragen set erklaerung = $q$Der RPO gibt an, wie viel Datenverlust maximal akzeptabel ist, gemessen in Zeit. Ein RPO von 1 Stunde bedeutet: maximal 1 Stunde Daten dürfen verloren gehen, also muss mindestens stündlich gesichert werden.$q$ where id = 211078;
update fragen set erklaerung = $q$Ein Immutable Backup kann nach dem Erstellen für einen festgelegten Zeitraum nicht mehr verändert oder gelöscht werden, auch nicht von Admins oder Ransomware. Das garantiert einen sauberen Wiederherstellungspunkt.$q$ where id = 211085;
update fragen set erklaerung = $q$Die zusätzliche „1" steht für eine Kopie offline oder immutable (Ransomware-Schutz). Die „0" steht für null Fehler beim Recovery-Test: Backups müssen regelmäßig getestet werden, um sicherzustellen dass sie wirklich funktionieren.$q$ where id = 211089;
update fragen set erklaerung = $q$Der RTO (Recovery Time Objective) ist kritisch, denn er bestimmt, wie schnell das System wieder läuft. Bei 50.000€/Stunde Verlust muss die Ausfallzeit (RTO) möglichst kurz sein, um Umsatzverluste zu minimieren.$q$ where id = 211093;
update fragen set erklaerung = $q$Ja, knapp. Das letzte Backup war um 2 Uhr, der Crash um 23 Uhr. Das sind 21 Stunden Datenverlust, also innerhalb des RPO von 24 Stunden. Bei RPO = 12 Stunden wäre es eine Verletzung gewesen.$q$ where id = 211095;
update fragen set erklaerung = $q$DNS wird oft mit einem Telefonbuch verglichen: Du kennst den Namen (Domain) und bekommst die zugehörige Nummer (IP-Adresse), genau wie im Telefonbuch Name zu Telefonnummer.$q$ where id = 211100;
update fragen set frage = $q$Was ist „de" in der Adresse „www.google.de"?$q$, erklaerung = $q$„de" ist die Top-Level-Domain (TLD), der oberste Teil ganz rechts. Weitere TLDs sind z.B. .com, .org, .net. „google" ist die Second-Level-Domain, „www" ist die Subdomain.$q$ where id = 211101;
update fragen set erklaerung = $q$Zuerst wird der Resolver gefragt. Das ist dein DNS-Server, oft beim Internet-Provider. Er übernimmt die weitere Abfrage über Root, TLD und autoritativen Server.$q$ where id = 211104;
update fragen set erklaerung = $q$Caching speichert DNS-Antworten zwischen, sodass wiederholte Abfragen nicht erneut die ganze Kette durchlaufen müssen. Die IP kommt dann sofort aus dem Zwischenspeicher. Das beschleunigt das Surfen.$q$ where id = 211107;
update fragen set erklaerung = $q$Der CNAME-Record (Canonical Name) ist ein Alias. Er verweist auf eine andere Domain statt auf eine IP-Adresse. So können mehrere Namen (z.B. www und shop) auf dasselbe Ziel zeigen.$q$ where id = 211114;
update fragen set erklaerung = $q$Die Kombination aus IP-Adresse und Port nennt man Socket. Beispiel: 93.184.216.34:443 ist ein Socket. Er adressiert einen bestimmten Dienst auf einem bestimmten Rechner.$q$ where id = 211119;
update fragen set erklaerung = $q$Port 443 wird von HTTPS genutzt, also für verschlüsselte Webseiten. Das „S" steht für Secure. Der unverschlüsselte Vorgänger HTTP nutzt Port 80.$q$ where id = 211123;
update fragen set erklaerung = $q$Port 22 wird von SSH (Secure Shell) genutzt, für sichere, verschlüsselte Fernwartung von Servern. Der unsichere Vorgänger Telnet nutzt Port 23.$q$ where id = 211124;
update fragen set erklaerung = $q$Port 25 wird von SMTP (Simple Mail Transfer Protocol) genutzt, zum Versenden von E-Mails. Zum Abrufen nutzt man POP3 (110) oder IMAP (143).$q$ where id = 211125;
update fragen set erklaerung = $q$Port 53 wird von DNS genutzt, also für die Namensauflösung. Über diesen Port werden Domainnamen in IP-Adressen übersetzt.$q$ where id = 211126;
update fragen set erklaerung = $q$Port 3306 wird von MySQL genutzt, einem weit verbreiteten Datenbanksystem. PostgreSQL nutzt dagegen Port 5432.$q$ where id = 211127;
update fragen set erklaerung = $q$Er nutzt SSH auf Port 22, also die sichere, verschlüsselte Fernwartung. Telnet (Port 23) wäre unsicher, da die Verbindung unverschlüsselt ist und Passwörter im Klartext übertragen würden.$q$ where id = 211128;
update fragen set erklaerung = $q$TCP ist verbindungsorientiert und zuverlässig. Es garantiert, dass alle Daten vollständig und in richtiger Reihenfolge ankommen. UDP ist verbindungslos und schneller, gibt aber keine Garantie für Vollständigkeit oder Reihenfolge.$q$ where id = 211130;
update fragen set erklaerung = $q$UDP eignet sich besser für Echtzeit, weil es schneller ist (kein Verbindungsaufbau, keine Bestätigungen). Bei Streaming ist Tempo wichtiger als Vollständigkeit: Ein verlorenes Paket fällt kaum auf, Verzögerung dagegen schon.$q$ where id = 211132;
update fragen set erklaerung = $q$Bei einem Port-Scan testet ein Angreifer systematisch, welche Ports auf einem System offen sind. Offene Ports verraten laufende Dienste und sind oft der erste Schritt zur Vorbereitung eines Angriffs.$q$ where id = 211134;
update fragen set erklaerung = $q$Wenn die Seite per IP erreichbar ist, funktionieren Server und Port. Geht nur der Name nicht, liegt ein DNS-Problem vor, z.B. ein fehlender oder falscher A-Record. Die Namensauflösung scheitert.$q$ where id = 211136;
update fragen set erklaerung = $q$Port 443 muss geöffnet sein. Das ist der Port für HTTPS (verschlüsseltes Web). Port 80 wäre nur für unverschlüsseltes HTTP. Für sichere Verbindungen ist 443 erforderlich.$q$ where id = 211139;
update fragen set erklaerung = $q$SSH nutzt Port 22 über TCP. Das ist korrekt. SSH braucht eine zuverlässige Verbindung (TCP) für die sichere Fernwartung. DNS nutzt dagegen meist UDP, HTTP nutzt 80 (nicht 443).$q$ where id = 211140;
update fragen set erklaerung = $q$RAID steht für Redundant Array of Independent Disks, ein Verbund aus mehreren unabhängigen Festplatten, die zusammen wie eine wirken.$q$ where id = 211143;
update fragen set erklaerung = $q$Mirroring bedeutet, Daten auf mehrere Platten zu spiegeln (kopieren). Fällt eine Platte aus, sind die Daten auf der anderen noch vorhanden. Das bietet Ausfallsicherheit, kostet aber Speicherplatz.$q$ where id = 211146;
update fragen set erklaerung = $q$RAID 0 nutzt Striping. Die Daten werden auf alle Platten verteilt. Das macht es sehr schnell, bietet aber keinen Schutz vor Plattenausfall.$q$ where id = 211149;
update fragen set erklaerung = $q$RAID 1 nutzt Mirroring. Die Daten werden auf zwei Platten gespiegelt. Jede Platte enthält dieselben Daten, was Ausfallsicherheit bietet.$q$ where id = 211151;
update fragen set erklaerung = $q$Wahr. Bei RAID 1 (Mirroring) enthält jede Platte dieselben Daten. Fällt eine aus, übernimmt die gespiegelte Kopie nahtlos. Die Daten bleiben erhalten.$q$ where id = 211154;
update fragen set erklaerung = $q$Bei großen Platten dauert der Rebuild nach einem Ausfall sehr lange. In dieser Zeit könnte eine ZWEITE Platte ausfallen, was RAID 5 nicht überlebt. RAID 6 verträgt zwei gleichzeitige Ausfälle und ist daher sicherer.$q$ where id = 211160;
update fragen set erklaerung = $q$RAID 10 kombiniert Mirroring (RAID 1) und Striping (RAID 0). Es spiegelt zuerst und stripet dann über die Spiegel-Paare. Dadurch bekommt man Sicherheit und Geschwindigkeit zugleich.$q$ where id = 211162;
update fragen set erklaerung = $q$RAID 10 benötigt mindestens 4 Festplatten, also zwei Spiegel-Paare, über die dann gestriped wird. Mit weniger als 4 Platten ist die Kombination aus Mirroring und Striping nicht möglich.$q$ where id = 211163;
update fragen set erklaerung = $q$RAID 10 wird oft für Datenbanken und performance-kritische Systeme empfohlen, weil es gleichzeitig hohe Geschwindigkeit (Striping) und gute Ausfallsicherheit (Mirroring) bietet, sofern das Budget für die doppelte Plattenzahl da ist.$q$ where id = 211165;
update fragen set erklaerung = $q$RAID 10 verliert die Hälfte der Kapazität (Spiegelung), während RAID 5 nur eine Platte für Parity opfert. RAID 10 ist also teurer pro nutzbarem TB, dafür schneller und beim Rebuild unkomplizierter.$q$ where id = 211166;
update fragen set erklaerung = $q$DAS ist Speicher, der direkt an einen einzelnen Rechner angeschlossen ist, z.B. eine interne oder USB-Festplatte. Er ist nur für diesen einen Rechner nutzbar und nicht über das Netzwerk teilbar.$q$ where id = 211175;
update fragen set frage = $q$Auf welcher Ebene greift ein NAS zu?$q$ where id = 211176;
update fragen set erklaerung = $q$Ein SAN ist ein eigenes Hochgeschwindigkeits-Netzwerk nur für Speicher. Server greifen auf Block-Ebene zu (wie auf eine lokale Platte). Das ist sehr schnell, aber teuer und komplex. Typisch für Rechenzentren.$q$ where id = 211177;
update fragen set frage = $q$Ein kleines Büro will, dass mehrere Mitarbeiter auf gemeinsame Dateien zugreifen können, einfach und kostengünstig. Welche Storage-Lösung passt am besten?$q$ where id = 211179;
update fragen set erklaerung = $q$RAID 10 kombiniert Tempo (Striping) und Sicherheit (Mirroring), ideal für Datenbanken. Kapazität: (8/2) × 2 = 8 TB. Die Hälfte geht durch Spiegelung verloren, dafür ist es schnell und sicher.$q$ where id = 211182;
update fragen set erklaerung = $q$Bei RAID 5 darf eine Platte ausfallen. Die Daten bleiben erhalten und werden aus der Parity rekonstruiert. Das System läuft weiter (im degradierten Modus), bis die defekte Platte ersetzt und der Rebuild abgeschlossen ist.$q$ where id = 211183;
update fragen set erklaerung = $q$Ein SAN (Storage Area Network) bietet Block-Zugriff über ein eigenes Hochgeschwindigkeitsnetz, ideal für Rechenzentren und Virtualisierung. NAS (Datei-Ebene) wäre zu langsam, DAS nicht zentral nutzbar.$q$ where id = 211185;
update fragen set erklaerung = $q$Die Aussage ist falsch. RAID schützt nur vor physischem Plattenausfall, nicht vor versehentlichem Löschen, Ransomware, Software-Fehlern oder Katastrophen. Ein Backup ist trotz RAID unbedingt nötig.$q$ where id = 211186;
update fragen set erklaerung = $q$Bei else if wird der Reihe nach geprüft. Der ERSTE zutreffende Fall wird ausgeführt, alle weiteren werden übersprungen, selbst wenn sie auch zutreffen würden.$q$ where id = 211203;
update fragen set erklaerung = $q$Die Schleife läuft mit i = 1, 2, 3, 4, 5, also 5 Mal. Da hier ab 1 gezählt wird und die Bedingung i <= 5 lautet (kleiner GLEICH), sind alle Werte von 1 bis 5 dabei.$q$ where id = 211209;
update fragen set erklaerung = $q$Das erste Element eines Arrays hat den Index 0, nicht 1. Arrays zählen ab 0. Das ist einer der häufigsten Anfängerfehler in der Programmierung.$q$ where id = 211216;
update fragen set erklaerung = $q$Eine natürliche Person ist ab der Geburt (Vollendung der Geburt) rechtsfähig, also fähig, Träger von Rechten und Pflichten zu sein. Diese Rechtsfähigkeit endet mit dem Tod.$q$ where id = 211233;
update fragen set erklaerung = $q$Ein 14-Jähriger ist beschränkt geschäftsfähig (Bereich 7-17 Jahre). Er kann Rechtsgeschäfte grundsätzlich nur mit Zustimmung der gesetzlichen Vertreter (Eltern) wirksam abschließen, mit Ausnahme des Taschengeldparagraphen.$q$ where id = 211236;
update fragen set erklaerung = $q$Eine Willenserklärung ist die Äußerung, eine bestimmte Rechtsfolge herbeiführen zu wollen, z.B. der erklärte Wille, etwas zu kaufen. Zwei übereinstimmende Willenserklärungen bilden einen Vertrag.$q$ where id = 211240;
update fragen set erklaerung = $q$Ein Vertrag entsteht durch Angebot und Annahme, also zwei übereinstimmende Willenserklärungen. Erst die Annahme des Angebots schließt den Vertrag.$q$ where id = 211243;
update fragen set erklaerung = $q$Eine Prokura ist eine umfassende Handlungsvollmacht. Der Prokurist darf fast alle Geschäfte tätigen, die der Betrieb des Handelsgewerbes mit sich bringt, mit wenigen Ausnahmen (z.B. Grundstücksverkauf, der besondere Vollmacht braucht).$q$ where id = 211275;
update fragen set erklaerung = $q$Der Vertrag ist schwebend unwirksam. Ein beschränkt Geschäftsfähiger (7-17) braucht für solche Geschäfte die Zustimmung der Eltern. Ohne sie ist der Vertrag schwebend unwirksam. Er wird erst durch Genehmigung wirksam oder endgültig unwirksam. Der Taschengeldparagraph greift bei Ratenzahlung nicht.$q$ where id = 211279;
update fragen set erklaerung = $q$Zuerst kann sie Nacherfüllung verlangen, also Reparatur oder Ersatzlieferung. Erst wenn die Nacherfüllung scheitert, kommen Minderung oder Rücktritt in Betracht.$q$ where id = 211282;
update fragen set erklaerung = $q$Eine Kapitalgesellschaft wie die GmbH eignet sich am besten, da die Haftung auf das Gesellschaftsvermögen beschränkt ist. Das Privatvermögen der Gesellschafter bleibt geschützt, anders als bei einer Personengesellschaft (OHG, GbR).$q$ where id = 211283;

commit;

